# -- unified 1:1/group-session sync ------------------------------------

#: Maps a unified session-sync failure reason to (HTTP status, field).
#: An unknown session (neither 1:1 nor group) is a 404; every device-side
#: problem (unknown, revoked, or not a session participant) is a 409
#: naming device_id, mirroring both message-read contracts.
_MESSAGE_SYNC_ERROR_MAP = {
    MESSAGE_SYNC_SESSION_UNKNOWN: (404, "session_id"),
    MESSAGE_SYNC_DEVICE_UNKNOWN: (409, "device_id"),
    MESSAGE_SYNC_DEVICE_INACTIVE: (409, "device_id"),
    MESSAGE_SYNC_DEVICE_NOT_PARTICIPANT: (409, "device_id"),
    MESSAGE_SYNC_CURSOR_CONFLICT: (409, "cursor"),
}

def _message_sync_error(self, error: MessageSyncError,
                        session_id: str) -> ServiceError:
    """Translate a storage :class:`MessageSyncError` into a ServiceError."""
    status_code, field = self._MESSAGE_SYNC_ERROR_MAP[error.reason]
    if error.reason == MESSAGE_SYNC_SESSION_UNKNOWN:
        text = f"session not found: {session_id}"
    elif error.reason == MESSAGE_SYNC_CURSOR_CONFLICT:
        text = "cursor is out of range or moved backwards"
    elif error.reason == MESSAGE_SYNC_DEVICE_UNKNOWN:
        text = "device_id is not a registered device"
    elif error.reason == MESSAGE_SYNC_DEVICE_INACTIVE:
        text = "device_id is revoked"
    else:
        text = "device_id is not a participant of this session"
    return ServiceError(text, field, status_code=status_code)

def sync_session_messages(self, session_id: str, device_id: str,
                          after: Optional[int], limit: int) -> Dict[str, Any]:
    """Return one ascending sync page of a 1:1 or group session's messages.

    With *after* ``None`` the device's stored cursor is the start and is
    advanced under the store lock (an empty page leaves it unchanged); an
    explicit non-negative *after* queries from there without touching the
    stored cursor. A 1:1 session authorizes its two endpoints; a group
    session the frozen member set. Unknown session is 404/session_id; an
    unknown, revoked or non-participant device is 409/device_id.
    """
    try:
        return self.store.message_sync_page(
            session_id, device_id, after, limit)
    except MessageSyncError as error:
        raise self._message_sync_error(error, session_id)

def sync_session_checkpoint(self, session_id: str,
                            payload: object) -> Tuple[Dict[str, Any], int]:
    """Validate and move a device's unified session-sync cursor.

    ``device_id`` must be a non-empty string and ``cursor`` an integer in
    ``0..max_sequence``. A forward move returns 201 with a refreshed
    ``updated_at``; an equal cursor returns 200 unchanged; a backward or
    out-of-range cursor returns 409/field=cursor. Unknown session is
    404/session_id; an unknown, revoked or non-participant device is
    409/device_id.
    """
    if not isinstance(payload, dict):
        raise ServiceError("request body must be a JSON object",
                           "request_body")
    if "device_id" not in payload:
        raise ServiceError("missing required field: device_id", "device_id")
    if not is_nonempty_string(payload["device_id"]):
        raise ServiceError(
            "field must be a non-empty string: device_id", "device_id")
    if "cursor" not in payload:
        raise ServiceError("missing required field: cursor", "cursor")
    cursor = payload["cursor"]
    # bool is a subclass of int; reject it explicitly.
    if not isinstance(cursor, int) or isinstance(cursor, bool):
        raise ServiceError("field must be an integer: cursor", "cursor")
    if cursor < 0:
        raise ServiceError("field must be a non-negative integer: cursor",
                           "cursor")

    try:
        view, advanced = self.store.message_sync_checkpoint(
            session_id, payload["device_id"], cursor)
    except MessageSyncError as error:
        raise self._message_sync_error(error, session_id)
    return view, 201 if advanced else 200

# -- messages ----------------------------------------------------------

def post_message(self, payload: object) -> Dict[str, Any]:
    """Validate a message-send payload and atomically append the message.

    ``sequence`` must continue the session's stream (starting at 1, no
    gaps or duplicates), ``message_id`` must be unique within the session,
    and ``nonce`` must not have been accepted before in the same session;
    each violation is a 409 naming the offending field, as is a
    revoked/unknown sender device. The identical nonce in a different
    session is allowed.
    """
    if not isinstance(payload, dict):
        raise ServiceError("request body must be a JSON object",
                           "request_body")

    for name in _MESSAGE_STRING_FIELDS:
        if name not in payload:
            raise ServiceError(f"missing required field: {name}", name)
        if not is_nonempty_string(payload[name]):
            raise ServiceError(
                f"field must be a non-empty string: {name}", name)

    if "sequence" not in payload:
        raise ServiceError("missing required field: sequence", "sequence")
    sequence = payload["sequence"]
    # bool is a subclass of int; reject it explicitly.
    if not isinstance(sequence, int) or isinstance(sequence, bool):
        raise ServiceError("field must be an integer: sequence", "sequence")

    try:
        message = self.store.append_message(
            payload["session_id"],
            payload["sender_device_id"],
            payload["message_id"],
            sequence,
            payload["nonce"],
            payload["ciphertext"])
    except MessageCreateError as error:
        raise self._message_create_error(error, payload)

    return self.store.message_view(message)

@staticmethod
def _message_create_error(error: MessageCreateError,
                          payload: Dict[str, Any]) -> ServiceError:
    """Translate a storage :class:`MessageCreateError` into a ServiceError."""

"""HTTP layer: JSON API over the standard library's ``http.server``."""
from __future__ import annotations

import json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from typing import Any, Dict, Optional, Tuple
from urllib.parse import parse_qs, unquote, urlsplit

from .persistence import PersistenceUnavailable
from .service import DeviceService, ServiceError

_DEVICES_PATH = "/v1/devices"
_PREKEYS_PATH = "/v1/prekeys"
_SESSIONS_PATH = "/v1/sessions"
_SESSIONS_FROM_CLAIM_PATH = "/v1/sessions/from-claim"
_SESSIONS_FROM_BATCH_CLAIM_PATH = "/v1/sessions/from-batch-claim"
_MESSAGES_PATH = "/v1/messages"
_MESSAGES_SUBMIT_PATH = "/v1/messages/submit"
_GROUPS_PATH = "/v1/groups"
_GROUP_SESSIONS_PATH = "/v1/group-sessions"
_PERSISTENCE_INTEGRITY_PATH = "/v1/persistence/integrity"
_PERSISTENCE_INTEGRITY_HISTORY_PATH = "/v1/persistence/integrity/history"
_PERSISTENCE_INTEGRITY_HISTORY_PAGE_PATH = \
    "/v1/persistence/integrity/history/page"

#: Sentinel meaning a 400 for a malformed body was already sent.
_BAD_REQUEST = object()


class DeviceHTTPHandler(BaseHTTPRequestHandler):
    """Routes for ``POST /v1/devices`` and ``GET /v1/devices/{device_id}``."""

    service: DeviceService  # injected via :func:`handler_for`

    def _send_data_file_unavailable(self) -> None:
        """Answer 503/field=data_file after a durable write was rolled back."""
        self._send_json(503, {
            "message": "state file is temporarily unavailable; the change "
                       "was not applied",
            "field": "data_file"})

    # -- routing ----------------------------------------------------------

    def do_POST(self) -> None:
        try:
            self._route_POST()
        except PersistenceUnavailable:
            self._send_data_file_unavailable()

    def _route_POST(self) -> None:
        path = urlsplit(self.path).path
        if path == _DEVICES_PATH:
            self._handle_register()
        elif path == _PREKEYS_PATH + "/claim-batch":
            self._handle_claim_prekey_batch()
        elif path == _PREKEYS_PATH + "/claim":
            self._handle_claim_prekey()
        elif path == _SESSIONS_FROM_BATCH_CLAIM_PATH:
            self._handle_create_sessions_from_batch_claim()
        elif path == _SESSIONS_FROM_CLAIM_PATH:
            self._handle_create_session_from_claim()
        elif path == _SESSIONS_PATH:
            self._handle_create_session()
        elif path.startswith(_SESSIONS_PATH + "/") \
                and path.endswith("/sync/checkpoint"):
            self._route_session_sync_checkpoint(path)
        elif path == _MESSAGES_PATH:
            self._handle_post_message()
        elif path == _MESSAGES_SUBMIT_PATH:
            self._handle_submit_message()
        elif path == _GROUPS_PATH:
            self._handle_create_group()
        elif path == _GROUP_SESSIONS_PATH:
            self._handle_create_group_session()
        elif path.startswith(_GROUP_SESSIONS_PATH + "/") \
                and path.endswith("/sync/checkpoint"):
            self._route_group_sync_checkpoint(path)
        elif path.startswith(_GROUP_SESSIONS_PATH + "/") \
                and path.endswith("/rotate"):
            self._route_rotate_group_session(path)
        elif path.startswith(_GROUPS_PATH + "/"):
            self._route_group_member(path)
        elif path.startswith(_DEVICES_PATH + "/") and path.endswith("/revoke"):
            self._route_revoke(path)
        elif path.startswith(_DEVICES_PATH + "/") \
                and path.endswith("/identity-key/rotate"):
            self._route_rotate_identity(path)
        elif path.startswith(_DEVICES_PATH + "/"):
            self._route_add_prekey(path)
        elif path.startswith(_MESSAGES_PATH + "/") and path.endswith("/acks"):
            self._route_acks(path)
        elif path.startswith(_MESSAGES_PATH + "/") and "/retry/" in path:
            self._route_retry(path)
        else:
            self._send_json(404, {"message": f"not found: {path}"})

    def _route_retry(self, path: str) -> None:
        suffix = path[len(_MESSAGES_PATH) + 1:]
        parts = suffix.split("/")
        if len(parts) == 3 and parts[1] == "retry" and parts[0] and parts[2]:
            self._handle_retry_message(unquote(parts[0]), unquote(parts[2]))
        else:
            self._send_json(404, {"message": "session not found",
                                  "field": "session_id"})

    def _route_acks(self, path: str) -> None:
        suffix = path[len(_MESSAGES_PATH) + 1:-len("/acks")]
        parts = suffix.split("/")
        if len(parts) == 1 and parts[0]:
            self._handle_ack_message(unquote(parts[0]))
        else:
            self._send_json(404, {"message": "session not found",
                                  "field": "session_id"})

    def _route_group_member(self, path: str) -> None:
        suffix = path[len(_GROUPS_PATH) + 1:]
        parts = suffix.split("/")
        if len(parts) == 2 and parts[0] and parts[1] == "members":
            self._handle_add_group_member(unquote(parts[0]))
        elif (len(parts) == 3 and parts[0] and parts[1] == "members"
                and parts[2] in ("add", "remove")):
            group_id = unquote(parts[0])
            if parts[2] == "add":
                self._handle_add_group_member(group_id)
            else:
                self._handle_remove_group_member(group_id)
        else:
            self._send_json(404, {"message": "group not found",
                                  "field": "group_id"})

    def _route_session_sync_checkpoint(self, path: str) -> None:
        suffix = path[len(_SESSIONS_PATH) + 1:
                      -len("/sync/checkpoint")]
        if suffix and "/" not in suffix:
            self._handle_sync_session_checkpoint(unquote(suffix))
        else:
            self._send_json(404, {"message": "session not found",
                                  "field": "session_id"})

    def _route_group_sync_checkpoint(self, path: str) -> None:
        suffix = path[len(_GROUP_SESSIONS_PATH) + 1:
                      -len("/sync/checkpoint")]
        if suffix and "/" not in suffix:
            self._handle_sync_checkpoint(unquote(suffix))
        else:
            self._send_json(404, {"message": "session not found",
                                  "field": "session_id"})

    def _route_rotate_group_session(self, path: str) -> None:
        suffix = path[len(_GROUP_SESSIONS_PATH) + 1:-len("/rotate")]
        if suffix and "/" not in suffix:
            self._handle_rotate_group_session(unquote(suffix))
        else:
            self._send_json(404, {"message": "session not found",
                                  "field": "session_id"})

    def _route_revoke(self, path: str) -> None:
        # Split on raw slashes only; a percent-encoded slash inside a segment
        # is part of the id, mirroring the GET route.
        suffix = path[len(_DEVICES_PATH) + 1:-len("/revoke")]

def _handle_show_session(self, session_id: str) -> None:
    try:
        body = self.service.get_session(session_id)
    except ServiceError as error:
        self._send_json(error.status_code, error.to_body())
        return
    self._send_json(200, body)

def _handle_create_group(self) -> None:
    payload = self._read_json_request()
    if payload is _BAD_REQUEST:
        return
    try:
        body = self.service.create_group(payload)
    except ServiceError as error:
        self._send_json(error.status_code, error.to_body())
        return
    self._send_json(201, body)

def _handle_show_group(self, group_id: str) -> None:
    try:
        body = self.service.get_group(group_id)
    except ServiceError as error:
        self._send_json(error.status_code, error.to_body())
        return
    self._send_json(200, body)

def _handle_add_group_member(self, group_id: str) -> None:
    payload = self._read_json_request()
    if payload is _BAD_REQUEST:
        return
    try:
        body, status_code = self.service.add_group_member(group_id, payload)
    except ServiceError as error:
        self._send_json(error.status_code, error.to_body())
        return
    self._send_json(status_code, body)

def _handle_remove_group_member(self, group_id: str) -> None:
    payload = self._read_json_request()
    if payload is _BAD_REQUEST:
        return
    try:
        body = self.service.remove_group_member(group_id, payload)
    except ServiceError as error:
        self._send_json(error.status_code, error.to_body())
        return
    self._send_json(200, body)

def _handle_create_group_session(self) -> None:
    payload = self._read_json_request()
    if payload is _BAD_REQUEST:
        return
    try:
        body = self.service.create_group_session(payload)
    except ServiceError as error:
        self._send_json(error.status_code, error.to_body())
        return
    self._send_json(201, body)

def _handle_show_group_session(self, session_id: str) -> None:
    try:
        body = self.service.get_group_session(session_id)
    except ServiceError as error:
        self._send_json(error.status_code, error.to_body())
        return
    self._send_json(200, body)

def _handle_rotate_group_session(self, session_id: str) -> None:
    payload = self._read_json_request()
    if payload is _BAD_REQUEST:
        return
    try:
        body, status_code = self.service.rotate_group_session(
            session_id, payload)
    except ServiceError as error:
        self._send_json(error.status_code, error.to_body())
        return
    self._send_json(status_code, body)

def _handle_sync_group_messages(self, session_id: str) -> None:
    params = self._sync_query_params()
    if params is None:
        return  # a 400 response was already sent
    device_id, after, limit = params
    try:
        body = self.service.sync_group_messages(
            session_id, device_id, after, limit)
    except ServiceError as error:
        self._send_json(error.status_code, error.to_body())
        return
    self._send_json(200, body)

def _handle_sync_checkpoint(self, session_id: str) -> None:
    payload = self._read_json_request()
    if payload is _BAD_REQUEST:
        return
    try:
        body, status_code = self.service.sync_group_checkpoint(
            session_id, payload)
    except ServiceError as error:
        self._send_json(error.status_code, error.to_body())
        return
    self._send_json(status_code, body)

def _handle_sync_session_messages(self, session_id: str) -> None:
    params = self._sync_query_params()
    if params is None:
        return  # a 400 response was already sent
    device_id, after, limit = params
    try:
        body = self.service.sync_session_messages(
            session_id, device_id, after, limit)
    except ServiceError as error:
        self._send_json(error.status_code, error.to_body())
        return
    self._send_json(200, body)

def _handle_sync_session_checkpoint(self, session_id: str) -> None:
    payload = self._read_json_request()
    if payload is _BAD_REQUEST:
        return
    try:
        body, status_code = self.service.sync_session_checkpoint(
            session_id, payload)
    except ServiceError as error:
        self._send_json(error.status_code, error.to_body())
        return
    self._send_json(status_code, body)

